        } else {
            displayText = getSubtitleText();
        }
        View root = CardBrowser.this.findViewById(R.id.root_layout);
        UIUtils.showSnackbar(CardBrowser.this,
                displayText,
                SNACKBAR_DURATION,
                R.string.card_browser_search_all_decks,
                (v) -> searchAllDecks(),
                root,
                null);

    }
};

