package com.ichi2.anki;

import android.app.Activity;
import android.content.Intent;

import com.ichi2.libanki.Note;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.Robolectric;
import org.robolectric.android.controller.ActivityController;

import androidx.test.ext.junit.runners.AndroidJUnit4;
import timber.log.Timber;

@RunWith(AndroidJUnit4.class)
public class RepoBrowserCrashTest extends RobolectricTest {

    @Test
    public void browserDoesNotCrashAfterNoteTypeChangeInMultiSelect() {
        addNoteUsingBasicModel("Hello", "World");
        addNoteUsingBasicModel("Hello2", "World2");

        ActivityController controller = Robolectric.buildActivity(CardBrowser.class, new Intent())
                .create().start().resume().visible();
        CardBrowser browser = (CardBrowser) controller.get();

        Timber.i("card count %d", browser.cardCount());
        browser.checkedCardsAtPositions(new int[] {0, 1});
        Timber.i("checked %d, multiselect %b", browser.checkedCardCount(), browser.isInMultiSelectMode());

        Intent data = new Intent();
        data.putExtra("reloadRequired", true);
        browser.onActivityResult(0, Activity.RESULT_CANCELED, data);

        org.robolectric.shadows.ShadowLooper.runUiThreadTasksIncludingDelayedTasks();
        Timber.i("survived, card count %d", browser.cardCount());
    }
}

package com.ichi2.anki;

import android.app.Activity;
import android.content.Intent;

import com.ichi2.libanki.Note;
import com.ichi2.utils.JSONObject;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.Robolectric;
import org.robolectric.android.controller.ActivityController;

import androidx.test.ext.junit.runners.AndroidJUnit4;
import timber.log.Timber;

@RunWith(AndroidJUnit4.class)
public class RepoBrowserCrashTest extends RobolectricTest {

    @Test
    public void browserDoesNotCrashAfterNoteTypeChangeInMultiSelect() {
        // a note with two cards ("Basic (and reversed card)")
        Note n = addNoteUsingModelName("Basic (and reversed card)", "Hello", "World");
        Timber.i("cards: %d", n.cards().size());

        ActivityController controller = Robolectric.buildActivity(CardBrowser.class, new Intent())
                .create().start().resume().visible();
        CardBrowser browser = (CardBrowser) controller.get();

        Timber.i("card count %d", browser.cardCount());
        browser.checkedCardsAtPositions(new int[] {0, 1});
        Timber.i("checked %d, multiselect %b", browser.checkedCardCount(), browser.isInMultiSelectMode());

        // Simulate the note type change performed in the NoteEditor: the second card is removed
        JSONObject basic = getCol().getModels().byName("Basic");
        JSONObject reversed = getCol().getModels().byName("Basic (and reversed card)");
        java.util.Map<Integer, Integer> fmap = new java.util.HashMap<>();
        fmap.put(0, 0);
        fmap.put(1, 1);
        java.util.Map<Integer, Integer> cmap = new java.util.HashMap<>();
        cmap.put(0, 0);
        getCol().modSchemaNoCheck();
        try {
            getCol().getModels().change(reversed, new long[] {n.getId()}, basic, fmap, cmap);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        Timber.i("cards after change: %d", getCol().cardCount());

        Intent data = new Intent();
        data.putExtra("reloadRequired", true);
        browser.onActivityResult(0, Activity.RESULT_CANCELED, data);

        org.robolectric.shadows.ShadowLooper.runUiThreadTasksIncludingDelayedTasks();
        Timber.i("survived, card count %d checked %d", browser.cardCount(), browser.checkedCardCount());
    }
}

