private long[] getSelectedCardIds() {
    //copy to array to ensure threadsafe iteration
    Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
    //the list of cards may have been reloaded since the selection was made (#6154), so only
    //handle the positions which are still valid.
    List<Map<String, String>> cards = getCards();
    List<Long> ids = new ArrayList<>(checkedPositions.length);
    for (int cardPosition : checkedPositions) {
        if (cardPosition < 0 || cardPosition >= cards.size()) {
            Timber.w("Ignoring invalid selected position: %d", cardPosition);
            continue;
        }
        String id = cards.get(cardPosition).get(ID);
        if (id == null) {
            continue;
        }
        ids.add(Long.valueOf(id));
    }
    long[] ret = new long[ids.size()];
    for (int i = 0; i < ids.size(); i++) {
        ret[i] = ids.get(i);
    }
    return ret;
}

private boolean hasSelectedSingleNoteId() {
    //Heuristic to skip a large array copy
    if (checkedCardCount() > 50) {
        return false;
    }
    //copy to array to ensure threadsafe iteration
    Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
    //the list of cards may have been reloaded since the selection was made (#6154), so only
    //handle the positions which are still valid.
    List<Map<String, String>> cards = getCards();
    HashSet<String> notes = new HashSet<>();
    for (Integer position : checkedPositions) {
        if (position == null || position < 0 || position >= cards.size()) {
            Timber.w("Ignoring invalid selected position: %s", position);
            continue;
        }
        String noteId = cards.get(position).get(NOTE);
        if (notes.add(noteId) && notes.size() > 1) {
            return false;
        }
    }
    return notes.size() == 1;

