/**
 * The positions stored in mCheckedCardPositions are only valid for the list of cards which was
 * displayed when the selection was performed. Once the list has been rebuilt (a search), the
 * positions have to be recalculated from the ids of the previously selected cards, otherwise
 * the browser will either operate on the wrong cards, or crash if cards were removed (#6154).
 */
private void restoreSelectionAfterSearch() {
    List<Long> previouslyCheckedIds = mCheckedCardIdsBeforeSearch;
    mCheckedCardIdsBeforeSearch = new ArrayList<>();
    mCheckedCardPositions.clear();

    if (!previouslyCheckedIds.isEmpty()) {
        Set<Long> idsToCheck = new HashSet<>(previouslyCheckedIds);
        List<Map<String, String>> cards = getCards();
        for (int i = 0; i < cards.size(); i++) {
            String id = cards.get(i).get(ID);
            if (id != null && idsToCheck.contains(Long.valueOf(id))) {
                mCheckedCardPositions.add(i);
            }
        }
    }

    //If none of the selected cards remain (they were deleted, or no longer match the search),
    //there is nothing left to act on, so leave multi-select mode.
    if (mInMultiSelectMode && mCheckedCardPositions.isEmpty()) {
        endMultiSelectMode();
    }
}


