@VisibleForTesting(otherwise = VisibleForTesting.PRIVATE)
public List<Long> getCheckedCardIds() {
    List<Long> cardIds = new ArrayList<>();
    //copy to array to ensure threadsafe iteration
    Integer[] checkedPositions = mCheckedCardPositions.toArray(new Integer[0]);
    List<Map<String, String>> cards = getCards();
    for (Integer pos : checkedPositions) {
        //the card list may have been reloaded since the selection was made (#6154)
        if (pos == null || pos < 0 || pos >= cards.size()) {
            Timber.w("Ignoring invalid selected position: %s", pos);
            continue;
        }
        String id = cards.get(pos).get(ID);
        if (id == null) {
            continue;
        }
        cardIds.add(Long.valueOf(id));
    }
    return cardIds;
}

