@Test
public void changingNoteTypeInMultiSelectModeDoesNotCrash() {
    //#6154 - the note type of a multi-selected note was changed in the NoteEditor, removing one
    //of the selected cards. The browser reloaded its list and used the (now invalid) positions.
    Note n = addNoteUsingModel("Basic (and reversed card)", "Hello", "World");
    assertThat("Note should have two cards", n.cards().size(), is(2));

    CardBrowser b = getBrowserWithNoNewCards();
    b.checkedCardsAtPositions(new int[] {0, 1});
    assertThat("Browser should be in multi-select mode", b.isInMultiSelectMode(), is(true));

    //Simulate what the NoteEditor does when the note type is changed to one with a single card
    changeNoteTypeToBasic(n);

    Intent reloadRequired = new Intent();
    reloadRequired.putExtra("reloadRequired", true);

    AnkiAssert.assertDoesNotThrow(() -> b.onActivityResult(0, Activity.RESULT_CANCELED, reloadRequired));

    assertThat("The removed card should no longer be displayed", b.cardCount(), is(1L));
    assertThat("The selection should only contain existing cards", b.checkedCardCount(), is(1));
    assertThat("The selected card should still exist", b.getCheckedCardIds().size(), is(1));
}

private void changeNoteTypeToBasic(Note n) {
    JSONObject basic = getCol().getModels().byName("Basic");
    JSONObject current = n.model();
    Map<Integer, Integer> fieldMap = new HashMap<>();
    fieldMap.put(0, 0);
    fieldMap.put(1, 1);
    Map<Integer, Integer> cardMap = new HashMap<>();
    cardMap.put(0, 0);
    getCol().modSchemaNoCheck();
    try {
        getCol().getModels().change(current, new long[] { n.getId() }, basic, fieldMap, cardMap);
    } catch (ConfirmModSchemaException e) {
        throw new RuntimeException(e);
    }
}

private Note addNoteUsingModel(String modelName, String... fields) {
    JSONObject model = getCol().getModels().byName(modelName);
    Note n = getCol().newNote(model);
    for (int i = 0; i < fields.length; i++) {
        n.setField(i, fields[i]);
    }
    if (getCol().addNote(n) == 0) {
        throw new IllegalStateException("note was not added");
    }
    return n;
}

